package com.example.nailsalon.entity; import jakarta.persistence.*; import jakarta.validation.constraints.*;
@Entity public class Appointment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotNull private Long clientId; @NotNull private Long masterId; @NotNull private Long serviceId; @NotBlank private String appointmentDate; @NotBlank private String status="BOOKED"; public Appointment(){} public Long getId(){return id;} public Long getClientId(){return clientId;} public void setClientId(Long v){clientId=v;} public Long getMasterId(){return masterId;} public void setMasterId(Long v){masterId=v;} public Long getServiceId(){return serviceId;} public void setServiceId(Long v){serviceId=v;} public String getAppointmentDate(){return appointmentDate;} public void setAppointmentDate(String v){appointmentDate=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
